effect.shader:
void main(){
    vec2 c = center/1000.0 + 0.5;
    vec2 d = acScreenNorm - c;
    d.x *= acScreenSize.x/acScreenSize.y;
    float dist = length(d);
    float ring = progress;
    float diff = dist - ring;
    float w = width;
    float force = (1.0 - smoothstep(0.0, w, abs(diff))) * sign(diff);
    force *= amplitude * 0.08 * (1.0-progress);
    vec2 uv = acScreenNorm + normalize(d+0.0001)*force;
    gl_FragColor = texture2DCv(inputImg.texture, uv);
}
